        int n, m, s, t;
        vector<int> adj[MAXN];
        Edge edges[MAXM * 2];

        void init(int nodes, int source, int sink) {
                n = nodes; m = 0; s = source; t = sink;
                for (int i = 0; i < n; ++i) adj[i].clear();
        }

