                adj[a].push_back(m);
                edges[m + 1].v = a; edges[m + 1].c = 0;
                adj[b].push_back(m + 1);
                m += 2;
        }

        int dist[MAXN], count[MAXN], cur[MAXN], parent[MAXN], pathLen;
