                                parent[v] = i;
                        }
                }
                ++count[dist[v]];
        }

        int sendFlow() {
                int flow = INT_MAX;
                int idx = -1;
                for (int i = 0; i < pathLen; ++i) {
                        auto &arc = edges[adj[parent[edges[adj[parent[0]]][0]]][i]];
                        if (arc.c < flow) {
                                flow = arc.c;
                                idx = i;
                        }
                }
                for (int i = 0; i < pathLen; ++i) {
                        int id = adj[parent[edges[adj[parent[0]]][i]]][i];
                        edges[id].c -= flow;
                        edges[RE(id)].c += flow;
                }
                pathLen = idx;
                return flow;
        }

        int maxFlow() {
                int totalFlow = 0;
                bfs();
                fill(cur, cur + n, 0);
                int u = s;
