import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 300;
    static final int MAXM = 65536;
    static final int INF = 1000000007;
    static final int[] dx = {-1, 0, 1, 0};
    static final int[] dy = {0, -1, 0, 1};

    static class Edge {
        int v, c;
        Edge(int v, int c) {
            this.v = v;
            this.c = c;
        }
    }

    static class Flow {
        int n, m, s, t;
        List<Integer>[] adj = new ArrayList[MAXN];
        Edge[] edges = new Edge[MAXM * 2];

        int[] dist = new int[MAXN], count = new int[MAXN], cur = new int[MAXN], parent = new int[MAXN];
        int pathLen;

        void init(int nodes, int source, int sink) {
            n = nodes;
            m = 0;
            s = source;
            t = sink;
            for (int i = 0; i < n; i++) {
                adj[i] = new ArrayList<>();
            }
        }

        void addEdge(int a, int b, int cap) {
            edges[m] = new Edge(b, cap);
            adj[a].add(m);
            edges[m + 1] = new Edge(a, 0);
            adj[b].add(m + 1);
            m += 2;
        }

        void bfs() {
            Arrays.fill(dist, n);
            Arrays.fill(count, 0);
            dist[t] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(t);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int id : adj[u]) {
                    int v = edges[id].v;
                    if (dist[v] == n && edges[RE(id)].c > 0) {
                        dist[v] = dist[u] + 1;
                        q.offer(v);
                    }
                }
            }
        }

        void relabel(int v) {
            count[dist[v]]--;
            dist[v] = n;
            for (int i = 0; i < adj[v].size(); i++) {
                Edge arc = edges[adj[v].get(i)];
                if (dist[v] > dist[arc.v] + 1 && arc.c > 0) {
                    dist[v] = dist[arc.v] + 1;
                    parent[v] = adj[v].get(i);
                }
            }
            count[dist[v]]++;
        }

        int sendFlow() {
            int flow = Integer.MAX_VALUE;
            int idx = -1;
            for (int i = 0; i < pathLen; i++) {
                int id = adj[parent[edges[adj[parent[0]]][0]]][i];
                Edge arc = edges[id];
                if (arc.c < flow) {
                    flow = arc.c;
                    idx = i;
                }
            }
            for (int i = 0; i < pathLen; i++) {
                int id = adj[parent[edges[adj[parent[0]]][i]]][i];
                edges[id].c -= flow;
                edges[RE(id)].c += flow;
            }
            pathLen = idx;
            return flow;
        }

        int maxFlow() {
            int totalFlow = 0;
            bfs();
            Arrays.fill(cur, 0);
            int u = s;
            parent[s] = -1;
            while (dist[s] != n) {
                if (u == t) {
                    totalFlow += sendFlow();
                    u = s;
                    continue;
                }
                boolean advanced = false;
                for (; cur[u] < adj[u].size(); cur[u]++) {
                    int id = adj[u].get(cur[u]);
                    Edge arc = edges[id];
                    if (dist[arc.v] == dist[u] - 1 && arc.c > 0) {
                        parent[arc.v] = id;
                        u = arc.v;
                        pathLen++;
                        advanced = true;
                        break;
                    }
                }
                if (!advanced) {
                    if (count[dist[u]] == 1) break;
                    relabel(u);
                    if (u != s) {
                        pathLen--;
                        u = edges[parent[u]].v;
                    }
                }
            }
            return totalFlow;
        }
    }

    static int nodeX(int i, int j) {
        return i * MAXN + j;
    }

    static int nodeY(int i, int j) {
        return MAXN * MAXN + i * MAXN + j;
    }

    static int sourceNode() {
        return MAXN * MAXN;
    }

    static int sinkNode() {
        return sourceNode() + 1;
    }

    static int totalNodes() {
        return sinkNode() + 1;
    }

    static int[][] grid = new int[MAXN][MAXN];
    static int[][] result = new int[MAXN][MAXN];
    static int[][] dist_map = new int[MAXN][MAXN];
    static int[][] time_map = new int[MAXN][MAXN];

    static void computeDistances(int size, char[][] gridChars, int[][] dist_map) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                dist_map[i][j] = INF;
            }
        }
        Queue<int[]> q = new LinkedList<>();
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (gridChars[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    dist_map[i][j] = 0;
                }
            }
        }
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int x = p[0], y = p[1];
            for (int k = 0; k < 4; k++) {
                int xx = x + dx[k], yy = y + dy[k];
                if (0 <= xx && xx < size && 0 <= yy && yy < size && Character.isDigit(gridChars[xx][yy]) && dist_map[xx][yy] == INF) {
                    dist_map[xx][yy] = dist_map[x][y] + 1;
                    q.offer(new int[]{xx, yy});
                }
            }
        }
    }

    static void process(int size, int maxDist, int startX, int startY, char[][] gridChars, char[][] resultChars, int[][] dist_map, int[][] time_map, Flow fn) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                time_map[i][j] = INF;
            }
        }
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{startX, startY});
        time_map[startX][startY] = 0;
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int x = p[0], y = p[1];
            if (time_map[x][y] > maxDist) break;
            if (time_map[x][y] <= dist_map[x][y] && Character.isDigit(resultChars[x][y]) && resultChars[x][y] != '0') {
                fn.addEdge(nodeX(startX, startY), nodeY(x, y), 11);
            }
            if (time_map[x][y] >= dist_map[x][y]) continue;
            for (int k = 0; k < 4; k++) {
                int xx = x + dx[k], yy = y + dy[k];
                if (0 <= xx && xx < size && 0 <= yy && yy < size && Character.isDigit(gridChars[xx][yy]) && time_map[xx][yy] == INF) {
                    time_map[xx][yy] = time_map[x][y] + 1;
                    q.offer(new int[]{xx, yy});
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int size = Integer.parseInt(st.nextToken());
        int maxDist = Integer.parseInt(st.nextToken());

        Flow fn = new Flow();
        fn.init(totalNodes(), sourceNode(), sinkNode());

        char[][] gridChars = new char[size][];
        for (int i = 0; i < size; i++) {
            gridChars[i] = br.readLine().toCharArray();
        }

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (Character.isDigit(gridChars[i][j]) && gridChars[i][j] != '0') {
                    fn.addEdge(sourceNode(), nodeX(i, j), gridChars[i][j] - '0');
                }
            }
        }

        char[][] resultChars = new char[size][];
        for (int i = 0; i < size; i++) {
            resultChars[i] = br.readLine().toCharArray();
        }

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (Character.isDigit(resultChars[i][j]) && resultChars[i][j] != '0') {
                    fn.addEdge(nodeY(i, j), sinkNode(), resultChars[i][j] - '0');
                }
            }
        }

        computeDistances(size, gridChars, dist_map);

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (Character.isDigit(gridChars[i][j]) && gridChars[i][j] != '0') {
                    process(size, maxDist, i, j, gridChars, resultChars, dist_map, time_map, fn);
                }
            }
        }

        System.out.println(fn.maxFlow());
    }

    static int RE(int i) {
        return i ^ 1;
    }
}
